  add('self_assessment', '정리', { title: '스스로 점검해요', items: ['📚 지식·이해 — ' + t.self[0][0], '🔧 과정·기능 — ' + t.self[0][1], '💛 가치·태도 — ' + t.self[0][2]], prompts: [t.self[1]] }, [id('e', 3)]);
  add('next_lesson', '정리', { title: idx === keys.length - 1 ? '다음 단원엔' : '다음 시간엔', preview: nk(t.nextText || (s.next + '. ' + s.next_q)), emoji: t.next }, [id('c', 1)]);
  const meta = { grade: 6, subject: '수학', term: 2, unit: 5, unit_title: UT, n, title: t.title, std: STD, duration_min: 40, lesson_format: t.fmt + ' · 2세대 19장(7요소)', theme: '생활 속 원의 둘레와 넓이', pages: PAGE[key] };
  if (Object.keys(CSRC).length) meta.concept_src = CSRC;
  if (s) { meta.live_url = LIVE + s.file; meta.source = DIR + s.file; } else meta.source = '지도서 304~305 · 334~335쪽 · 『수학』 114~115쪽 (자기주도 원문 없음)';
